        tn.getWholeText();
        assertEquals("test", tn.text());
    }

    @Test
    public void isBlankTestWhenFalse() {
        TextNode tn = new TextNode("test");
        assertFalse(tn.isBlank());
    }

    @Test
    public void isBlankTestWhenTrue() {
        TextNode tn = new TextNode("  ");
        assertTrue(tn.isBlank());
    }

    @Test
    public void splitTextTest() {
        TextNode tn = new TextNode("test");
        TextNode newTn = tn.splitText(2);
        assertEquals("te", tn.getWholeText());
        assertEquals("st", newTn.getWholeText());
    }

    @Test
    public void outerHtmlHeadTest() throws IOException {
        TextNode tn = new TextNode("test");
        StringBuilder sb = new StringBuilder();
        tn.outerHtmlHead(sb, 0, new Document.OutputSettings());
        assertEquals("test", sb.toString());
    }

    @Test
    public void outerHtmlTailTest() throws IOException {
        TextNode tn = new TextNode("test");
        StringBuilder sb = new StringBuilder();
        tn.outerHtmlTail(sb, 0, new Document.OutputSettings());
        assertEquals("", sb.toString());
    }

    @Test
    public void cloneTest() {
        TextNode tn = new TextNode("test");
        TextNode clone = tn.clone();
        assertFalse(tn == clone);
        assertEquals(tn.text(), clone.text());
    }

    @Test
    public void createFromEncodedWhenNotNullTest() {
        TextNode tn = TextNode.createFromEncoded("test&", false);
        assertEquals("test&", tn.text());
    }

    @Test
    public void normaliseWhitespaceTest() {
        String result = TextNode.normaliseWhitespace("  test  ");
        assertEquals(" test ", result);
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        String result = TextNode.stripLeadingWhitespace("  test  ");
        assertEquals("test  ", result);
    }

    @Test
    public void lastCharIsWhitespaceTestWhenTrue() {
        boolean result = TextNode.lastCharIsWhitespace(new StringBuilder(" "));
        assertTrue(result);
    }

    @Test
    public void lastCharIsWhitespaceTestWhenFalse() {
        boolean result = TextNode.lastCharIsWhitespace(new StringBuilder("not space"));
        assertFalse(result);
    }
